```javascript
/**
 * Converts an identifier to snake_case.
 * 
 * @param {string} name
 * @returns {string}
 */
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (name === '') {
    return '';
  }

  // 1. Handle camelCase/PascalCase boundaries:
  // - Between lowercase/digit and uppercase: "aB" -> "a_B", "1B" -> "1_B"
  // - Before the last capital in a run of capitals followed by lowercase: "XMLFile" -> "XML_File"
  let result = name
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  // 2. Replace spaces, tabs, and hyphens with underscores
  result = result.replace(/[\s-]+/g, '_');

  // 3. Convert to lowercase
  result = result.toLowerCase();

  // 4. Collapse multiple underscores into one
  // Note: The requirement says "__init__" becomes "_init_".
  // This implies we only collapse internal sequences, but keep leading/trailing 
  // if they were part of the original structure.
  // Actually, the rule says "Runs of _ collapse into a single _".
  // Let's normalize all sequences of underscores to a single underscore.
  result = result.replace(/_+/g, '_');

  return result;
}
