/**
 * Roman numerals, strictly.
 */

const ROMAN_MAP = [
  { val: 1000, sym: 'M' },
  { val: 900, sym: 'CM' },
  { val: 500, sym: 'D' },
  { val: 400, sym: 'CD' },
  { val: 100, sym: 'C' },
  { val: 90, sym: 'XC' },
  { val: 50, sym: 'L' },
  { val: 40, sym: 'XL' },
  { val: 10, sym: 'X' },
  { val: 9, sym: 'IX' },
  { val: 5, sym: 'V' },
  { val: 4, sym: 'IV' },
  { val: 1, sym: 'I' }
];

/**
 * Converts an integer from 1 to 3999 to its Roman numeral.
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let num = n;

  for (const { val, sym } of ROMAN_MAP) {
    while (num >= val) {
      result += sym;
      num -= val;
    }
  }

  return result;
}

/**
 * Converts a Roman numeral back to a number, strictly.
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  if (text.length === 0) {
    throw new RangeError('Input cannot be empty.');
  }

  // Validate that the input is exactly the canonical form
  // We check this by re-encoding the result of a potential conversion
  // or by verifying the input against the output of toRoman.
  // Since we need to parse it, we can use a regex that matches the canonical structure:
  // M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})
  const canonicalRegex = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  if (!canonicalRegex.test(text)) {
    throw new RangeError('Invalid or non-canonical Roman numeral.');
  }

  let result = 0;
  let remaining = text;

  for (const { val, sym } of ROMAN_MAP) {
    while (remaining.startsWith(sym)) {
      result += val;
      remaining = remaining.slice(sym.length);
    }
  }

  if (remaining.length > 0 || result === 0) {
    throw new RangeError('Invalid Roman numeral.');
  }

  // Final check: ensure the parsed number generates the exact same string
  if (toRoman(result) !== text) {
    throw new RangeError('Non-canonical Roman numeral.');
  }

  return result;
}
