/**
 * Flattens nested arrays up to a specific depth.
 * @param {Array} items 
 * @param {number} depth 
 * @returns {Array}
 */
export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  const isDepthValid =
    depth === Infinity ||
    (Number.isInteger(depth) && depth >= 0);

  if (!isDepthValid) {
    throw new RangeError('depth must be a non-negative integer or Infinity');
  }

  function recursiveFlatten(arr, currentDepth) {
    let result = [];
    for (const item of arr) {
      if (currentDepth > 0 && Array.isArray(item)) {
        result.push(...recursiveFlatten(item, currentDepth - 1));
      } else {
        result.push(item);
      }
    }
    return result;
  }

  return recursiveFlatten(items, depth);
}
