    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  // 3: Replace spaces, tabs, and hyphens with underscores.
  result = result.replace(/[\s-]+/g, '_');

  // 4: Lowercase everything.
  result = result.toLowerCase();

  // 5: Collapse multiple underscores into one.
  // Note: The requirement says __init__ becomes _init_. 
  // This implies we should collapse consecutive underscores, 
  // but keep leading/trailing ones if they were present.
  // However, the rule says "Runs of _ collapse into a single _, including at the start/end".
  // So __init__ -> _init_ is actually a result of collapsing.
  result = result.replace(/_+/g, '_');

  return result;
}
