/**
 * Groups items in an array by a key or a grouping function.
 * 
 * @param {Array} items - The array of items to group.
 * @param {string|Function} key - The property name or function to determine the group.
 * @returns {Map} A Map where keys are the group identifiers and values are arrays of items.
 * @throws {TypeError} If items is not an array or key is not a string/function.
 */
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  const isKeyString = typeof key === 'string';
  const isKeyFunction = typeof key === 'function';

  if (!isKeyString && !isKeyFunction) {
    throw new TypeError('key must be a string or a function');
  }

  const map = new Map();

  items.forEach((item, index) => {
    let groupKey;

    if (isKeyFunction) {
      groupKey = key(item, index);
    } else {
      // If item is null or undefined, the key is undefined
      if (item === null || item === undefined) {
        groupKey = undefined;
      } else {
        groupKey = item[key];
      }
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  });

  return map;
}
