/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex breakdown:
  // ^(\d+(?:\.\d+)?)(ms|s|m|h|d|w)$
  // Matches a number (digits, optional dot+digits) followed by a unit.
  // We split by whitespace and validate each component.
  const components = trimmed.split(/\s+/);
  const seenUnits = new Set();
  let totalMs = 0;

  for (const comp of components) {
    const match = comp.match(/^(\d+(?:\.\d+)?)(ms|s|m|h|d|w)$/);

    if (!match) {
      throw new RangeError(`Invalid component format: ${comp}`);
    }

    const [, valueStr, unit] = match;

    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);

    const value = parseFloat(valueStr);
    totalMs += value * units[unit];
  }

  return Math.round(totalMs);
}
