/**
 * Converts text to title case based on specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace while preserving it
  const parts = text.split(/(\s+)/);

  const words = parts.map((part, index) => {
    // If it's whitespace, return as is
    if (/^\s+$/.test(part)) return part;

    // Split by hyphens to handle rule 2
    const subParts = part.split('-');
    const processedSubParts = subParts.map((subPart) => {
      // Rule 1: Acronyms
      if (/^[A-Z]{2,}$/.test(subPart)) return subPart;

      // Rule 3: Capitalizing
      const lower = subPart.toLowerCase();
      const capitalized = lower.replace(/([a-z])/, (match) => match.toUpperCase());
      return capitalized;
    });

    const word = processedSubParts.join('-');

    // Rule 4: Small words
    // Find the index of the word in the original sequence of words
    const wordIndices = parts.reduce((acc, p, i) => {
      if (!/^\s+$/.test(p)) acc.push(i);
      return acc;
    }, []);

    const wordPos = wordIndices.indexOf(index);
    const isFirst = wordPos === 0;
    const isLast = wordPos === wordIndices.length - 1;

    if (smallWords.has(word.toLowerCase()) && !isFirst && !isLast) {
      return word.toLowerCase();
    }

    return word;
  });

  return words.join('');
}
