/**
 * Wraps text into lines of at most `width` characters.
 * 
 * @param {string} text 
 * @param {number} width 
 * @returns {string[]}
 */
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('Text must be a string.');
  }

  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('Width must be an integer of at least 1.');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) {
    return [];
  }

  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    if (word.length > width) {
      // If current line has content, push it first
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      // Break the long word into chunks of `width`
      for (let i = 0; i < word.length; i += width) {
        const chunk = word.slice(i, i + width);
        if (chunk.length === width) {
          lines.push(chunk);
        } else {
          currentLine = [chunk];
          currentLength = chunk.length;
        }
      }
    } else {
      // Check if word fits on current line
      // Need: currentLength (existing) + 1 (space) + word.length
      const spaceNeeded = currentLine.length > 0 ? 1 : 0;
      if (currentLength + spaceNeeded + word.length <= width) {
        currentLine.push(word);
        currentLength += spaceNeeded + word.length;
      } else {
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}
