/**
 * Parses a URL query string into an object.
 * 
 * @param {string} query
 * @returns {Object}
 */
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);

  if (query.startsWith('?')) {
    query = query.slice(1);
  }

  if (!query) {
    return result;
  }

  const pairs = query.split('&');

  for (const pair of pairs) {
    if (pair === '') continue;

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    const key = decode(rawKey);
    const value = decode(rawValue);

    const isArrayKey = key.endsWith('[]');
    const finalKey = isArrayKey ? key.slice(0, -2) : key;

    if (isArrayKey) {
      if (!(finalKey in result)) {
        result[finalKey] = [];
      }
      result[finalKey].push(value);
    } else {
      if (!(finalKey in result)) {
        result[finalKey] = value;
      } else {
        const existing = result[finalKey];
        if (Array.isArray(existing)) {
          existing.push(value);
        } else {
          result[finalKey] = [existing, value];
        }
      }
    }
  }

  return result;
}

/**
 * Decodes a query component: '+' to space, then URI decoding.
 * @param {string} str 
 * @returns {string}
 */
function decode(str) {
  const plusReplaced = str.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(plusReplaced);
  } catch (e) {
    throw new RangeError('Malformed percent-encoding');
  }
}
