  const componentRegex = /(\d+(?:\.\d+)?)(ms|s|m|h|d|w)/g;

  let totalMs = 0;
  const foundUnits = new Set();
  let matchCount = 0;
  let lastIndex = 0;

  const matches = [...trimmed.matchAll(componentRegex)];

  // Validate that the entire string was consumed by valid components
  let currentPos = 0;
  for (const match of matches) {
    const fullMatch = match[0];
    const index = trimmed.indexOf(fullMatch, currentPos);

    // Check for invalid characters between matches
    if (index !== currentPos) {
      throw new RangeError('Invalid format');
    }

    const value = parseFloat(match[1]);
    const unit = match[2];

    if (foundUnits.has(unit)) {
      throw new RangeError('Duplicate unit');
    }

    foundUnits.add(unit);
    totalMs += value * units[unit];

    currentPos = index + fullMatch.length;
    matchCount++;
  }

  // If we didn't consume the whole string or found no matches
  if (currentPos !== trimmed.length || matchCount === 0) {
    throw new RangeError('Invalid format');
  }

  return Math.round(totalMs);
}
