/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if input is invalid or malformed
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex breakdown:
  // ^\s* matches start
  // (\d+(?:\.\d+)?) matches number (must have digits before and after decimal if present)
  // ([a-z]+) matches unit
  // \s* matches optional whitespace
  // The global regex matches all components
  const componentRegex = /(\d+(?:\.\d+)?)([a-z]+)/g;
  const matches = [...trimmed.matchAll(componentRegex)];

  // Validate that the entire string was consumed by the regex
  // We remove all valid components and whitespace; if anything remains, it's invalid
  let remaining = trimmed;
  for (const match of matches) {
    remaining = remaining.replace(match[0], '');
  }
  if (remaining.trim() !== '') {
    throw new RangeError('Invalid format');
  }

  let totalMs = 0;
  const seenUnits = new Set();

  for (const match of matches) {
    const value = parseFloat(match[1]);
    const unit = match[2];

    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Unknown unit: ${unit}`);
    }
    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);
    totalMs += value * units[unit];
  }

  return Math.round(totalMs);
}
