/**
 * Converts text to title case according to specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace but keep the delimiters
  const parts = text.split(/(\s+)/);

  const words = [];
  const wordIndices = [];

  parts.forEach((part, index) => {
    if (!/^\s+$/.test(part) && part !== '') {
      words.push(part);
      wordIndices.push(index);
    }
  });

  const processedWords = words.map((word, i) => {
    const isFirst = i === 0;
    const isLast = i === words.length - 1;

    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) {
      return word;
    }

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false, false, smallWords)).join('-');
    }

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirst && !isLast) {
      return lower;
    }

    // Rule 3: Capitalizing
    return processWord(word, true, true, smallWords);
  });

  // Reconstruct
  wordIndices.forEach((originalIndex, i) => {
    parts[originalIndex] = processedWords[i];
  });

  return parts.join('');
}

function processWord(word, forceCap, allowSmall, smallWords) {
  const lower = word.toLowerCase();

  // Find first letter index
  let firstLetterIdx = -1;
  for (let i = 0; i < lower.length; i++) {
    if (/[a-z]/.test(lower[i])) {
      firstLetterIdx = i;
      break;
    }
  }

  if (firstLetterIdx === -1) return lower;

  const chars = lower.split('');
  chars[firstLetterIdx] = chars[firstLetterIdx].toUpperCase();
  return chars.join('');
}
