/**
 * Turns text into a URL-safe slug.
 * 
 * @param {string} text 
 * @param {{maxLength?: number}} [options] 
 * @returns {string}
 */
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const maxLength = options.maxLength;
  if (maxLength !== undefined && (!Number.isInteger(maxLength) || maxLength <= 0)) {
    throw new RangeError('maxLength must be a positive integer');
  }

  // 1. Normalise Unicode NFKD and remove combining marks (U+0300 to U+036F)
  let slug = text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');

  // 2. Lowercase
  slug = slug.toLowerCase();

  // 3. Replace non-alphanumeric chars with a single hyphen
  // 4. Remove hyphens from start and end
  slug = slug
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (maxLength !== undefined && slug.length > maxLength) {
    slug = slug.substring(0, maxLength);
    // Remove trailing hyphens again after cutting
    slug = slug.replace(/-+$/g, '');
  }

  return slug;
}
