/**
 * Parses a single line of CSV into an array of strings.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if the CSV format is invalid
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;

  while (i <= line.length) {
    if (i < line.length && line[i] === '"') {
      // Quoted field
      let field = '';
      i++; // Skip opening quote
      let closed = false;

      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) throw new RangeError('Unclosed quoted field');

      // After closing quote, must be comma or end of string
      if (i < line.length && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      result.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let start = i;
      let end = line.indexOf(',', i);
      if (end === -1) end = line.length;

      let field = line.substring(start, end);
      if (field.includes('"')) {
        throw new RangeError('Quote found in unquoted field');
      }

      result.push(field);
      i = end + 1;
    }

    // Handle trailing comma case: if line ends with ',', 
    // the loop logic above needs to ensure the last empty field is added.
    if (i === line.length + 1 && line.endsWith(',')) {
      result.push('');
      break;
    }
  }

  return result;
}
