/**
 * Parses a URL query string into an object.
 * 
 * @param {string} query
 * @returns {Object}
 */
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);

  if (query.startsWith('?')) {
    query = query.slice(1);
  }

  if (!query) return result;

  const pairs = query.split('&');

  for (const pair of pairs) {
    if (pair === '') continue;

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    const decode = (str) => {
      const plusToSpace = str.replace(/\+/g, ' ');
      try {
        return decodeURIComponent(plusToSpace);
      } catch (e) {
        throw new RangeError('Malformed percent-escape');
      }
    };

    let key = decode(rawKey);
    const value = decode(rawValue);
    let isArray = false;

    if (key.endsWith('[]')) {
      key = key.slice(0, -2);
      isArray = true;
    }

    if (!(key in result)) {
      result[key] = isArray ? [value] : value;
    } else {
      const existing = result[key];
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        result[key] = [existing, value];
      }
    }
  }

  return result;
}
