/**
 * Merges overlapping intervals.
 * 
 * @param {Array<Array<number>>} intervals
 * @returns {Array<Array<number>>}
 */
export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("Input must be an array.");
  }

  // Validate structure and values
  const validated = intervals.map((interval) => {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError("Each interval must be an array of two numbers.");
    }
    const [start, end] = interval;
    if (
      typeof start !== "number" ||
      typeof end !== "number" ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    ) {
      throw new RangeError("Interval values must be finite numbers.");
    }
    if (start > end) {
      throw new RangeError("Start cannot be greater than end.");
    }
    return [start, end];
  });

  if (validated.length === 0) {
    return [];
  }

  // Sort by start time (creating a new array to avoid mutation)
  const sorted = [...validated].sort((a, b) => a[0] - b[0]);

  const result = [];
  let current = [...sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const next = sorted[i];

    // If next interval starts before or exactly when the current ends, merge
    if (next[0] <= current[1]) {
      current[1] = Math.max(current[1], next[1]);
    } else {
      // No overlap, push current and move to next
      result.push(current);
      current = [...next];
    }
  }

  result.push(current);
  return result;
}
