/**
 * Flattens nested arrays up to a specified depth.
 * @param {Array} items 
 * @param {number} depth 
 * @returns {Array}
 */
export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  const isDepthValid =
    depth === Infinity ||
    (Number.isInteger(depth) && depth >= 0);

  if (!isDepthValid) {
    throw new RangeError('depth must be a non-negative integer or Infinity');
  }

  if (depth === 0) {
    return [...items];
  }

  const result = [];

  for (const item of items) {
    if (Array.isArray(item) && depth > 0) {
      result.push(...flatten(item, depth - 1));
    } else {
      result.push(item);
    }
  }

  return result;
}
