/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex breakdown:
  // ^\s* matches start
  // (\d+(?:\.\d+)?) matches number (digits, optional dot + digits)
  // ([a-z]+) matches unit
  // \s* matches trailing space
  // The global flag /g is used to iterate through all components
  const regex = /(\d+(?:\.\d+)?)([a-z]+)/g;
  const seenUnits = new Set();
  let totalMs = 0;
  let matchCount = 0;
  let lastIndex = 0;

  let match;
  while ((match = regex.exec(trimmed)) !== null) {
    // Check if there's any invalid character between matches
    const gap = trimmed.substring(lastIndex, match.index).trim();
    if (gap !== '') {
      throw new RangeError('Invalid format');
    }

    const [full, valStr, unit] = match;
    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Unknown unit: ${unit}`);
    }
    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);
    totalMs += parseFloat(valStr) * units[unit];
    matchCount += full.length;
    lastIndex = regex.lastIndex;
  }

  // Ensure the entire string was consumed
  if (lastIndex !== trimmed.length) {
    throw new RangeError('Invalid format');
  }

  return Math.round(totalMs);
}
