/**
 * Converts text to title case based on specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace but keep the whitespace structure
  const parts = text.split(/(\s+)/);

  const words = parts.map((part, index, arr) => {
    // If it's whitespace, return as is
    if (/^\s+$/.test(part)) return part;

    // Identify if it's the first or last actual word
    const allWords = arr.filter(p => !/^\s+$/.test(p));
    const currentWordIndex = allWords.indexOf(part);
    const isFirst = currentWordIndex === 0;
    const isLast = currentWordIndex === allWords.length - 1;

    return processWord(part, isFirst, isLast, smallWords);
  });

  return words.join('');
}

function processWord(word, isFirst, isLast, smallWords) {
  // Rule 2: Hyphenated words
  if (word.includes('-')) {
    return word.split('-').map(part => processWord(part, false, false, smallWords)).join('-');
  }

  // Rule 1: Acronyms
  if (/^[A-Z]{2,}$/.test(word)) {
    return word;
  }

  // Rule 4: Small words
  const lower = word.toLowerCase();
  if (smallWords.has(lower) && !isFirst && !isLast) {
    return lower;
  }

  // Rule 3: Capitalizing
  // Find first letter index
  const firstLetterIdx = word.search(/[a-zA-Z]/);
  if (firstLetterIdx === -1) return word;

  return (
    word.slice(0, firstLetterIdx) +
    word[firstLetterIdx].toUpperCase() +
    word.slice(firstLetterIdx + 1).toLowerCase()
  );
}
