/**
 * Formats a byte count into a human-readable string.
 * 
 * @param {number} bytes 
 * @param {Object} [options]
 * @param {boolean} [options.binary=false]
 * @param {number} [options.decimals=1]
 * @returns {string}
 */
export function formatBytes(bytes, options = {}) {
  const { binary = false, decimals = 1 } = options;

  if (typeof bytes !== 'number') {
    throw new TypeError('Bytes must be a number');
  }
  if (!Number.isFinite(bytes) || bytes < 0) {
    throw new RangeError('Bytes must be a non-negative finite number');
  }
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 3) {
    throw new RangeError('Decimals must be an integer between 0 and 3');
  }

  const base = binary ? 1024 : 1000;
  const units = binary
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB']
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB'];

  let value = Math.round(bytes);

  if (value < base) {
    return `${value} B`;
  }

  let unitIndex = 0;
  let divisor = 1;

  // Find the appropriate unit
  while (unitIndex < units.length - 1 && value / Math.pow(base, unitIndex + 1) >= 1) {
    unitIndex++;
  }

  divisor = Math.pow(base, unitIndex);
  let result = value / divisor;

  // Rounding logic
  const factor = Math.pow(10, decimals);
  result = Math.round(result * factor) / factor;

  // Check if rounding pushed us to the next unit
  if (result >= base && unitIndex < units.length - 1) {
    result /= base;
    unitIndex++;
  }

  // Formatting
  const formattedValue = decimals === 0 
    ? Math.round(result).toString() 
    : result.toFixed(decimals);

  return `${formattedValue} ${units[unitIndex]}`;
}
